def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的臺灣位置、地圖資料與自然環境推理能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的絕對或相對位置、自然條件、尺度與要解釋的結果。", f"整理證據：把位置事實、可能機制與仍需補查的資料分開；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」能完整回應題幹而沒有過度外推。", "排除誘答：檢查是否把位置直接等同產業、風險或服務結果，或忽略地形、時間、群體與資料尺度。", "結論回查：確認資料範圍足以支持結論；改變地區、季節或尺度時必須重新判讀。"]
    return {"id": f"question-social-content-geo-aa-iv-3-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-aa-iv-3"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫臺灣地理位置特性情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-aa-iv-3", "examPatternRefs": refs, "solutionStrategy": "先分絕對位置、相對位置與尺度，再把位置連到交通、產業、季風或災害機制，最後檢查是否有足夠資料支持。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-aa-iv-3-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(DATA)} questions")
